<?php require_once __DIR__.'/app_private/bootstrap.php';$token=$_GET['token']??'';$st=db()->prepare('SELECT q.*,c.name customer_name,c.email customer_email,u.business_name owner_name,s.business_logo,s.currency,s.currency_symbol,s.currency_symbol_position,s.currency_decimal_separator,s.currency_thousands_separator,s.currency_decimals FROM quotes q JOIN customers c ON c.id=q.customer_id JOIN users u ON u.id=q.user_id LEFT JOIN settings s ON s.user_id=q.user_id WHERE q.public_token=?');$st->execute([$token]);$q=$st->fetch();if(!$q){http_response_code(404);exit('Quote not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$decision=$_POST['decision']??'';if(in_array($decision,['accepted','rejected'],true)){db()->prepare('UPDATE quotes SET status=? WHERE id=?')->execute([$decision,$q['id']]);db()->prepare('INSERT INTO notifications(user_id,kind,message,entity_type,entity_id) VALUES(?,?,?,?,?)')->execute([$q['user_id'],'quote_'.$decision,$q['customer_name'].' '.$decision.' quote '.$q['quote_number'],'quote',$q['id']]);flash('success','Your response has been recorded.');redirect('/public_quote.php?token='.urlencode($token));}}
$st=db()->prepare('SELECT * FROM quote_items WHERE quote_id=?');$st->execute([$q['id']]);$items=$st->fetchAll();$fm=fn(float $amount)=>format_money($amount,$q);page_header('Quote '.$q['quote_number'],true);?><article class="doc"><?php $logo=logo_src($q['business_logo']??''); if($logo):?><img class="doc-logo" src="<?=e($logo)?>" alt="<?=e($q['owner_name'])?> logo"><?php endif;?><div class="doc-brandname"><?=e($q['owner_name'])?></div><h1>Quote <?=e($q['quote_number'])?></h1><p><strong>From:</strong> <?=e($q['owner_name'])?><br><strong>For:</strong> <?=e($q['customer_name'])?></p><div class="mobile-table"><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['description'])?></td><td><?=e((string)$i['qty'])?></td><td><?=$fm((float)$i['unit_price'])?></td><td><?=$fm((float)$i['line_total'])?></td></tr><?php endforeach;?></tbody></table></div><div class="totals"><div><span>Subtotal</span><span><?=$fm((float)$q['subtotal'])?></span></div><div><span>Tax</span><span><?=$fm((float)$q['tax'])?></span></div><div class="grand"><span>Total</span><span><?=$fm((float)$q['total'])?></span></div></div><p>Status: <span class="badge <?=e($q['status'])?>"><?=e($q['status'])?></span></p><?php if(!in_array($q['status'],['accepted','rejected'],true)):?><form method="post" class="actions"><?=csrf_field()?><button name="decision" value="accepted">Accept quote</button><button class="btn danger" name="decision" value="rejected">Decline quote</button></form><?php endif;?></article><?php page_footer();?>
